class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_num = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_num[i] = prefix_num[i - 1] + nums[i - 1]
            prefix_cost[i] = prefix_cost[i - 1] + cost[i - 1]

        INF = 10**18
        dp = [INF] * (n + 1)
        dp[0] = 0

        for m in range(1, n + 1):
            new_dp = [INF] * (n + 1)
            for i in range(m, n + 1):
                for j in range(m - 1, i):
                    if dp[j] == INF:
                        continue
                    total_num = prefix_num[i] + k * m
                    total_cost_sub = prefix_cost[i] - prefix_cost[j]
                    current_cost = dp[j] + total_num * total_cost_sub
                    if current_cost < new_dp[i]:
                        new_dp[i] = current_cost
            dp = new_dp

        return min(dp[1:])

