class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def solve(n):
            if n == 0:
                return 0
            digits = list(map(int, str(n)))
            total = 0
            max_sum = 9 * len(digits)
            for s in range(1, max_sum + 1):
                memo = {}
                def dp(pos, tight, current_sum, current_prod_mod):
                    if current_sum > s:
                        return 0
                    if pos == len(digits):
                        return 1 if (current_sum == s and current_prod_mod == 0) else 0
                    state = (pos, tight, current_sum, current_prod_mod)
                    if state in memo:
                        return memo[state]

                    upper = digits[pos] if tight else 9
                    res = 0
                    for d in range(0, upper + 1):
                        new_tight = tight and (d == upper)
                        new_sum = current_sum + d
                        if new_sum > s:
                            continue
                        new_prod_mod = (current_prod_mod * d) % s if s > 0 else 0
                        res += dp(pos + 1, new_tight, new_sum, new_prod_mod)
                    memo[state] = res
                    return res

                total += dp(0, True, 0, 0)
            return total

        return solve(r) - solve(l - 1)

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n
        if n == k:
            return [0] * n

        prefix_count = {}
        for word in words:
            for j in range(1, len(word) + 1):
                prefix = word[:j]
                prefix_count[prefix] = prefix_count.get(prefix, 0) + 1

        max_len = 0
        for word in words:
            if len(word) > max_len:
                max_len = len(word)

        max1 = [0] * (max_len + 1)
        max2 = [0] * (max_len + 1)

        for prefix, count in prefix_count.items():
            L = len(prefix)
            if count > max1[L]:
                max2[L] = max1[L]
                max1[L] = count
            elif count > max2[L]:
                max2[L] = count

        L0 = 0
        for L in range(1, max_len + 1):
            if max1[L] >= k:
                L0 = L

        ans = [0] * n
        for i in range(n):
            word = words[i]
            if len(word) < L0:
                ans[i] = L0
            else:
                start_L = min(len(word), L0)
                found = False
                for L in range(start_L, 0, -1):
                    prefix = word[:L]
                    h = prefix_count[prefix]
                    if h >= k + 1:
                        ans[i] = L
                        found = True
                        break
                    else:
                        if h == max1[L]:
                            alt = max2[L]
                        else:
                            alt = max1[L]
                        if alt >= k:
                            ans[i] = L
                            found = True
                            break
                if not found:
                    ans[i] = 0
        return ans

