                if r < m1:
                    m2 = m1
                    m1 = r
                elif r < m2:
                    m2 = r
            min1[l] = m1
            min2[l] = m2

        suff_min = [10**9] * (n + 2)
        suff_min[n] = min_r[n]
        for i in range(n - 1, 0, -1):
            suff_min[i] = min(min_r[i], suff_min[i + 1])

        base_total = 0
        base_prefix_sum = [0] * (n + 1)
        current_sum = 0
        for i in range(1, n + 1):
            end_index = suff_min[i] - 1
            start_index = i - 1
            if end_index >= start_index:
                count = end_index - start_index + 1
            else:
                count = 0
            current_sum += count
            base_prefix_sum[i] = current_sum
        base_total = current_sum

        max_total = base_total

        for a, b in conflictingPairs:
            l = min(a, b)
            r = max(a, b)
            if r == min1[l]:
                new_min_r_l = min2[l]
            else:
                new_min_r_l = min1[l]

            if new_min_r_l == min_r[l]:
                total_here = base_total
            else:
                new_suff_min = [10**9] * (n + 2)
                if l < n:
                    new_suff_min[l] = min(new_min_r_l, suff_min[l + 1])
                else:
                    new_suff_min[l] = new_min_r_l

                for i in range(l - 1, 0, -1):
                    new_suff_min[i] = min(min_r[i], new_suff_min[i + 1])

                new_prefix_sum = 0
                for i in range(1, l + 1):
                    end_index = new_suff_min[i] - 1
                    start_index = i - 1
                    if end_index >= start_index:
                        count = end_index - start_index + 1
                    else:
                        count = 0
                    new_prefix_sum += count

                total_here = base_total - base_prefix_sum[l] + new_prefix_sum

            if total_here > max_total:
                max_total = total_here

        return max_total

