class FenwTreeMax:
    def __init__(self, size):
        self.size = size
        self.tree = [(-1, -1)] * (size + 1)

    def update(self, index, value):
        i = index
        while i <= self.size:
            if value[0] > self.tree[i][0]:
                self.tree[i] = value
            i += i & -i

    def query(self, index):
        res = (-1, -1)
        i = index
        while i > 0:
            if self.tree[i][0] > res[0]:
                res = self.tree[i]
            i -= i & -i
        return res

class FenwTreeMin:
    def __init__(self, size):
        self.size = size
        self.tree = [(10**18, -1)] * (size + 1)

    def update(self, index, value):
        i = index
        while i <= self.size:
            if value[0] < self.tree[i][0]:
                self.tree[i] = value
            i += i & -i

    def query(self, index):
        res = (10**18, -1)
        i = index
        while i <= self.size:
            if self.tree[i][0] < res[0]:
                res = self.tree[i]
            i += i & -i
        return res

