class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Map each point to its perimeter position
        def get_perimeter(p):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        # Precompute perimeter positions and sort points accordingly
        perimeter_points = []
        for p in points:
            perimeter_points.append((get_perimeter(p), p))
        perimeter_points.sort(key=lambda x: x[0])

        # Extract the sorted points (only the coordinates)
        sorted_points = [p for _, p in perimeter_points]

        # Function to check if it's possible to choose k points with min distance >= mid
        def can_select(mid):
            # We need to select at least k points
            count = 1
            last_x, last_y = sorted_points[0]
            for i in range(1, len(sorted_points)):
                x, y = sorted_points[i]
                # Calculate Manhattan distance
                dist = abs(x - last_x) + abs(y - last_y)
                if dist >= mid:
                    count += 1
                    last_x, last_y = x, y
                    if count >= k:
                        return True
            return False

        # Binary search for the maximum minimum distance
        low = 0
        high = 2 * side  # Maximum possible Manhattan distance on the square
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

