        return
    N = int(data[0])
    grid = []
    for i in range(1, 1+N):
        grid.append(data[i].strip())

    INF = 10**9
    dist = [[INF] * N for _ in range(N)]
    in_edges = [defaultdict(list) for _ in range(N)]
    out_edges = [defaultdict(list) for _ in range(N)]

    for i in range(N):
        for j in range(N):
            c = grid[i][j]
            if c != '-':
                out_edges[i][c].append(j)
                in_edges[j][c].append(i)

    queue = deque()

    for i in range(N):
        dist[i][i] = 0
        queue.append((i, i))

    for i in range(N):
        for j in range(N):
            if i != j and grid[i][j] != '-':
                dist[i][j] = 1
                queue.append((i, j))

    while queue:
        k, l = queue.popleft()
        d = dist[k][l]
        for label, x_list in in_edges[k].items():
            if label in out_edges[l]:
                y_list = out_edges[l][label]
                for x in x_list:
                    for y in y_list:
                        if d + 2 < dist[x][y]:
                            dist[x][y] = d + 2
                            queue.append((x, y))

    for i in range(N):
        row = []
        for j in range(N):
            if dist[i][j] == INF:
                row.append("-1")
            else:
                row.append(str(dist[i][j]))
        print(" ".join(row))

