class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        pre = parts[0]
        mid = parts[1]
        suf = parts[2]

        pre_ends = []
        if pre:
            start = 0
            n = len(s)
            len_pre = len(pre)
            while start <= n - len_pre:
                idx = s.find(pre, start)
                if idx == -1:
                    break
                pre_ends.append(idx + len_pre)
                start = idx + 1

        suf_starts = []
        if suf:
            start = 0
            n = len(s)
            len_suf = len(suf)
            while start <= n - len_suf:
                idx = s.find(suf, start)
                if idx == -1:
                    break
                suf_starts.append(idx)
                start = idx + 1

        mid_occ = []
        if mid:
            start = 0
            n = len(s)
            len_mid = len(mid)
            while start <= n - len_mid:
                idx = s.find(mid, start)
                if idx == -1:
                    break
                mid_occ.append((idx, idx + len_mid))
                start = idx + 1
        else:
            mid_occ = [(i, i) for i in range(len(s) + 1)]

        min_len = float('inf')

        for m_start, m_end in mid_occ:
            if pre:
                idx_in_pre = bisect.bisect_right(pre_ends, m_start)
                if idx_in_pre == 0:
                    continue
                e1 = pre_ends[idx_in_pre - 1]
            else:
                e1 = m_start

            if suf:
                idx_in_suf = bisect.bisect_left(suf_starts, m_end)
                if idx_in_suf == len(suf_starts):
                    continue
                s2 = suf_starts[idx_in_suf]
            else:
                s2 = m_end

            current_len = (s2 + len(suf)) - (e1 - len(pre))
            if current_len < min_len:
                min_len = current_len

        return min_len if min_len != float('inf') else -1

