class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(target)
        total_masks = 1 << n

        lcm_cache = [1] * total_masks
        for mask in range(1, total_masks):
            current_lcm = 1
            for i in range(n):
                if mask & (1 << i):
                    current_lcm = math.lcm(current_lcm, target[i])
            lcm_cache[mask] = current_lcm

        min_cost = [float('inf')] * total_masks
        for mask in range(1, total_masks):
            lcm_val = lcm_cache[mask]
            for num in nums:
                remainder = num % lcm_val
                cost = (lcm_val - remainder) % lcm_val
                if cost < min_cost[mask]:
                    min_cost[mask] = cost

        dp = [float('inf')] * total_masks
        dp[0] = 0

        for mask in range(1, total_masks):
            sub = mask
            while sub:
                if dp[mask ^ sub] + min_cost[sub] < dp[mask]:
                    dp[mask] = dp[mask ^ sub] + min_cost[sub]
                sub = (sub - 1) & mask

        return dp[total_masks - 1]

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = 10**18

        cnt_lt = [[0] * (n + 1) for _ in range(26)]
        sum_lt = [[0] * (n + 1) for _ in range(26)]
        cnt_ge = [[0] * (n + 1) for _ in range(26)]
        sum_ge = [[0] * (n + 1) for _ in range(26)]

        for v in range(26):
            for i in range(1, n + 1):
                char_val = ord(caption[i - 1])
                cnt_lt[v][i] = cnt_lt[v][i - 1] + (1 if char_val < v else 0)
                sum_lt[v][i] = sum_lt[v][i - 1] + (char_val if char_val < v else 0)
                cnt_ge[v][i] = cnt_ge[v][i - 1] + (1 if char_val >= v else 0)
                sum_ge[v][i] = sum_ge[v][i - 1] + (char_val if char_val >= v else 0)

        def compute_cost(l, r, v):
            count_lt = cnt_lt[v][r + 1] - cnt_lt[v][l]
            sum_lt_val = sum_lt[v][r + 1] - sum_lt[v][l]
            count_ge = cnt_ge[v][r + 1] - cnt_ge[v][l]
            sum_ge_val = sum_ge[v][r + 1] - sum_ge[v][l]
            return v * count_lt - sum_lt_val + sum_ge_val - v * count_ge

        dp = [INF] * (n + 1)
        dp[0] = 0
        parent = [None] * (n + 1)

        for i in range(1, n + 1):
            for L in range(3, i + 1):
                l = i - L
                r = i - 1
                for v in range(26):
                    cost_seg = compute_cost(l, r, v)
                    total = dp[l] + cost_seg
                    if total < dp[i]:
                        dp[i] = total
                        parent[i] = (l, v, L)
                    elif total == dp[i]:
                        if parent[i] is not None:
                            cur_v = parent[i][1]
                            cur_L = parent[i][2]
                            if v < cur_v or (v == cur_v and L > cur_L):
                                parent[i] = (l, v, L)

        if dp[n] == INF:
            return ""

        res = [''] * n
        i = n
        while i > 0:
            l, v, L = parent[i]
            char = chr(v + ord('a'))
            for j in range(l, i):
                res[j] = char
            i = l

        return "".join(res)

