    results = []

    for i in range(T):
        N = int(data[i+1])

        if N == 1:
            results.append("2 1")
            continue

        if N <= 60:
            A = 2
            M = (1 << N) - 1  # 2^N - 1
            results.append(f"{A} {M}")
            continue

        # For N > 60
        # Find a prime M = k*N + 1
        found = False
        k = 1
        while not found:
            M = k * N + 1
            if M > 10**18:
                # This should not happen for reasonable k
                break
            if is_prime(M):
                # Find smallest A >= 2 such that order of A mod M is N
                # Conditions:
                # 1. A^N ≡ 1 (mod M)
                # 2. For each prime factor p of N, A^(N/p) ≢ 1 (mod M)

                prime_factors = get_prime_factors(N)

                A = 2
                while True:
                    if A >= M:
                        # Should not happen if M is large enough and we have a generator
                        break

                    # Check condition 1
                    if mod_pow(A, N, M) != 1:
                        A += 1
                        continue

                    # Check condition 2
                    valid = True
                    for p in prime_factors:
                        if mod_pow(A, N // p, M) == 1:
                            valid = False
                            break

                    if valid:
                        found = True
                        break
                    else:
                        A += 1

                results.append(f"{A} {M}")
                break
            k += 1

    print('\n'.join(results))

