class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        sorted_intervals = []
        for i, (l, r, w) in enumerate(intervals):
            sorted_intervals.append((l, r, w, i))

        sorted_intervals.sort(key=lambda x: (x[1], x[0], x[3]))

        next_non_overlap = [-1] * n
        for i in range(n):
            l_i, r_i, w_i, orig_i = sorted_intervals[i]
            for j in range(i + 1, n):
                if sorted_intervals[j][0] > r_i:
                    next_non_overlap[i] = j
                    break

        NEG_INF = -10**18
        dp = [[(NEG_INF, -1)] * (n + 1) for _ in range(5)]
        took = [[False] * n for _ in range(5)]

        for k in range(1, 5):
            for i in range(n - 1, -1, -1):
                l, r, w, orig_i = sorted_intervals[i]

                cand1 = dp[k][i + 1] if i + 1 < n else (NEG_INF, -1)

                if k == 1:
                    cand2 = (w, orig_i)
                else:
                    j = next_non_overlap[i]
                    if j == -1:
                        cand2 = (NEG_INF, -1)
                    else:
                        res = dp[k - 1][j]
                        if res[0] == NEG_INF:
                            cand2 = (NEG_INF, -1)
                        else:
                            cand2 = (w + res[0], orig_i)

                if cand2[0] > cand1[0]:
                    dp[k][i] = cand2
                    took[k][i] = True
                elif cand2[0] < cand1[0]:
                    dp[k][i] = cand1
                    took[k][i] = False
                else:
                    if cand2[1] < cand1[1]:
                        dp[k][i] = cand2
                        took[k][i] = True
                    else:
                        dp[k][i] = cand1
                        took[k][i] = False

        result = []
        k = 4
        i = 0
        while k > 0 and i < n:
            if took[k][i]:
                result.append(sorted_intervals[i][3])
                l, r, w, orig_i = sorted_intervals[i]
                j = next_non_overlap[i]
                k -= 1
                i = j if j != -1 else i + 1
            else:
                i += 1

        return result

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)

        def kadane_standard(arr):
            if not arr:
                return 0
            max_so_far = arr[0]
            current_max = arr[0]
            for i in range(1, len(arr)):
                current_max = max(arr[i], current_max + arr[i])
                max_so_far = max(max_so_far, current_max)
            return max_so_far

        global_max = kadane_standard(nums)
        ans = global_max

        from collections import defaultdict
        indices_map = defaultdict(list)
        for i, num in enumerate(nums):
            indices_map[num].append(i)

        for x, positions in indices_map.items():
            positions.sort()
            segments = []
            start = 0
            for p in positions:
                if start <= p - 1:
                    segments.append(nums[start:p])
                start = p + 1
            if start <= n - 1:
                segments.append(nums[start:])

            if not segments:
                continue

            seg_info = []
            for seg in segments:
                if not seg:
                    seg_info.append((0, 0, 0))
                    continue
                m = len(seg)
                max_sub = seg[0]
                current_end = seg[0]
                for i in range(1, m):
                    current_end = max(seg[i], current_end + seg[i])
                    max_sub = max(max_sub, current_end)

                max_pref = seg[0]
                current_pref = seg[0]
                for i in range(1, m):
                    current_pref = max(current_pref + seg[i], seg[i])
                    max_pref = max(max_pref, current_pref)

                max_suff = seg[-1]
                current_suff = seg[-1]
                for i in range(m-2, -1, -1):
                    current_suff = max(seg[i], current_suff + seg[i])
                    max_suff = max(max_suff, current_suff)

                seg_info.append((max_sub, max_pref, max_suff))
                if max_sub > ans:
                    ans = max_sub

            for i in range(len(seg_info) - 1):
                if seg_info[i][2] + seg_info[i+1][1] > ans:
                    ans = seg_info[i][2] + seg_info[i+1][1]

        return ans

