class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        n = len(nums)

        def nCr(n, r):
            if r < 0 or r > n:
                return 0
            if r == 0 or r == n:
                return 1
            if r > n // 2:
                r = n - r
            res = 1
            for i in range(r):
                res = res * (n - i) // (i + 1)
            return res

        total = 0
        for i in range(2, n - 2):
            x = nums[i]
            left_part = nums[0:i]
            right_part = nums[i+1:n]

            from collections import defaultdict
            freq_left = defaultdict(int)
            for num in left_part:
                freq_left[num] += 1
            freq_right = defaultdict(int)
            for num in right_part:
                freq_right[num] += 1

            count_x_left = freq_left[x]
            count_x_right = freq_right[x]
            L_non_x = i - count_x_left
            R_non_x = (n - 1 - i) - count_x_right

            for a in range(0, min(2, count_x_left) + 1):
                for b in range(0, min(2, count_x_right) + 1):
                    ways_x = nCr(count_x_left, a) * nCr(count_x_right, b)
                    threshold = 1 + a + b
                    k = 2 - a
                    m = 2 - b

                    if threshold >= 3:
                        ways_non_x = nCr(L_non_x, k) * nCr(R_non_x, m)
                        total = (total + ways_x * ways_non_x) % mod
                    elif threshold == 2:
                        if a + b == 1:
                            if a == 1 and b == 0:
                                total_ways = 0
                                for v, count_v in freq_left.items():
                                    if v == x:
                                        continue
                                    r_count = R_non_x - freq_right.get(v, 0)
                                    total_ways = (total_ways + count_v * nCr(r_count, 2)) % mod
                                ways_non_x = total_ways
                                total = (total + ways_x * ways_non_x) % mod
                            elif a == 0 and b == 1:
                                total_ways = 0
                                for w, count_w in freq_right.items():
                                    if w == x:
                                        continue
                                    l_count = L_non_x - freq_left.get(w, 0)
                                    total_ways = (total_ways + count_w * nCr(l_count, 2)) % mod
                                ways_non_x = total_ways
                                total = (total + ways_x * ways_non_x) % mod
        return total % mod

