class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        num_set = set(nums)
        parent = list(range(threshold + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return False
            parent[rx] = ry
            return True

        components = len(nums)
        for a in nums:
            if a > threshold:
                continue
            b = 2 * a
            while b <= threshold:
                if b in num_set:
                    if union(a, b):
                        components -= 1
                b += a
        return components
